$lang = currentLang();
$pageTitle = t('nav.map_search') ?: 'Haritada Ara';
$moduleFilter = (string)($_GET['module'] ?? '');
$categoryFilter = (int)($_GET['category_id'] ?? 0);
$countryFilter = (int)($_GET['country_id'] ?? ($_GET['country'] ?? 0));
$cityFilter = (int)($_GET['city_id'] ?? ($_GET['city'] ?? 0));
$distanceKm = (int)($_GET['distance'] ?? 25);
if (!in_array($distanceKm, [5, 10, 15, 25, 50, 75, 100, 150], true)) $distanceKm = 25;

$countryCol = $lang === 'nl' ? 'name_nl' : ($lang === 'en' ? 'name_en' : 'name_tr');
$mapCategories = [];
$categoryParents = [];
$mapCountries = [];
$mapCities = [];
try {
    $mapCountries = $pdo->query("SELECT id, code, {$countryCol} AS name FROM countries WHERE is_active = 1 ORDER BY sort_order ASC, id ASC")->fetchAll(PDO::FETCH_ASSOC);
    $cityStmt = $pdo->query("SELECT id, country_id, name FROM cities WHERE is_active = 1 ORDER BY name ASC");
    foreach ($cityStmt->fetchAll(PDO::FETCH_ASSOC) as $city) { $mapCities[(int)$city['country_id']][] = $city; }
    
    $categoryStmt = $pdo->prepare("SELECT c.id, c.parent_id, c.module, c.slug, c.icon, COALESCE(ct.name, tr.name, c.slug) AS name FROM categories c LEFT JOIN category_translations ct ON ct.category_id = c.id AND ct.lang = ? LEFT JOIN category_translations tr ON tr.category_id = c.id AND tr.lang = 'tr' WHERE c.is_active = 1 ORDER BY c.parent_id IS NOT NULL ASC, c.sort_order ASC, c.id ASC");
    $categoryStmt->execute([$lang]);
    foreach ($categoryStmt->fetchAll(PDO::FETCH_ASSOC) as $category) {
        $mapCategories[(int)$category['id']] = $category;
        if (empty($category['parent_id'])) $categoryParents[] = $category;
    }
} catch (Exception $e) {}

$where = ["l.status IN ('active','reserved')"];
$params = [];

if (in_array($moduleFilter, ['esnaf','ikinci_el','emlak','arac'], true)) {
    $where[] = "l.module = :module";
    $params['module'] = $moduleFilter;
}

if ($categoryFilter > 0) {
    $where[] = "(l.category_id = :cat_id OR l.category_id IN (SELECT id FROM categories WHERE parent_id = :cat_id_sub))";
    $params['cat_id'] = $categoryFilter;
    $params['cat_id_sub'] = $categoryFilter;
}

if ($countryFilter > 0) {
    $where[] = "l.country_id = :country_id";
    $params['country_id'] = $countryFilter;
}

if ($cityFilter > 0) {
    $where[] = "l.city_id = :city_id";
    $params['city_id'] = $cityFilter;
}

$ws = implode(' AND ', $where);

$stmt = $pdo->prepare("SELECT l.id, l.title, l.description, l.price, l.latitude, l.longitude, l.module, l.image, l.country_id, l.city_id,
    (SELECT filename FROM listing_images WHERE listing_id = l.id ORDER BY is_cover DESC, sort_order ASC LIMIT 1) AS gallery_image,
    ci.name AS city_name, co.code AS country_code, co.{$countryCol} AS country_name
    FROM listings l
    LEFT JOIN cities ci ON ci.id = l.city_id
    LEFT JOIN countries co ON co.id = l.country_id
    WHERE {$ws}
    ORDER BY l.is_premium DESC, l.is_featured DESC, l.created_at DESC
    LIMIT 300");
$stmt->execute($params);
$mapListings = $stmt->fetchAll(PDO::FETCH_ASSOC);

