    1 => [52.1326, 5.2913],   // NL
    2 => [51.1657, 10.4515],  // DE
    3 => [50.8503, 4.3517],   // BE
    4 => [46.2276, 2.2137],   // FR
    5 => [47.5162, 14.5501],  // AT
    9 => [56.2639, 9.5018],   // DK
    11 => [38.9637, 35.2433], // TR
    12 => [51.9194, 19.1451]  // PL
];

foreach ($mapListings as &$listing) {
    $cityKey = strtolower(trim((string)($listing['city_name'] ?? '')));
    $coords = $cityCoordinates[$cityKey] ?? null;
    
    if (!$coords && !empty($listing['title'])) {
        $titleLower = strtolower($listing['title']);
        foreach ($cityCoordinates as $cName => $cPos) {
            if (str_contains($titleLower, $cName)) {
                $coords = $cPos;
                if (empty($listing['city_name'])) {
                    $listing['city_name'] = ucfirst($cName);
                }
                break;
            }
        }
    }
    
    if (!$coords && !empty($listing['country_id']) && isset($countryCoordinates[(int)$listing['country_id']])) {
        $coords = $countryCoordinates[(int)$listing['country_id']];
    }
    
    if (!is_numeric($listing['latitude']) || !is_numeric($listing['longitude'])) {
        if (!$coords) {
            $listing['latitude'] = null;
            $listing['longitude'] = null;
            continue;
        }
        $offset = ((int)$listing['id'] % 7 - 3) * 0.0035;
        $listing['latitude'] = $coords[0] + $offset;
        $listing['longitude'] = $coords[1] + $offset;
    }
    
    $resolvedImage = null;
    $imgCandidates = array_filter([
        $listing['image'] ?? null,
        $listing['gallery_image'] ?? null,
        'img_' . (int)$listing['id'] . '_1.jpg',
        'listing_' . (int)$listing['id'] . '_1.jpg'
    ]);
    
    $searchDirs = [
        __DIR__ . '/../uploads/listings/' . (int)$listing['id'] . '/',
        __DIR__ . '/../uploads/listings/',
        __DIR__ . '/../uploads/vehicles/' . (int)$listing['id'] . '/',
        __DIR__ . '/../uploads/vehicles/',
        __DIR__ . '/../uploads/'
    ];
    
    foreach ($imgCandidates as $cand) {
        $candClean = ltrim(str_replace(['listings/', 'vehicles/'], '', $cand), '/');
        foreach ($searchDirs as $dir) {
            if (is_file($dir . $candClean)) {
                $relPath = str_replace(__DIR__ . '/../uploads/', '', $dir . $candClean);
                $resolvedImage = BASE_URL . '/uploads/' . str_replace('%2F', '/', rawurlencode($relPath));
                break 2;
            }
            if (is_file($dir . $cand)) {
                $relPath = str_replace(__DIR__ . '/../uploads/', '', $dir . $cand);
                $resolvedImage = BASE_URL . '/uploads/' . str_replace('%2F', '/', rawurlencode($relPath));
                break 2;
            }
        }
    }
    
    if (!$resolvedImage) {
        $resolvedImage = BASE_URL . '/uploads/listings/property-placeholder.png';
    }
    
    $listing['image_url'] = $resolvedImage;
}
unset($listing);

if (isset($_GET['ajax']) && $_GET['ajax'] === 'postcode') {
    header('Content-Type: application/json; charset=utf-8');
    $postcode = strtoupper(preg_replace('/\s+/', '', (string)($_GET['postcode'] ?? '')));
    $countryCode = strtoupper((string)($_GET['country'] ?? ''));
    $cityId = (int)($_GET['city'] ?? 0);
    
    $point = null;
    try {
        $postStmt = $pdo->prepare("SELECT p.lat, p.lng FROM postcodes p INNER JOIN countries co ON co.id = p.country_id WHERE (p.postcode_normalized = ? OR p.postcode = ?) AND (? = '' OR co.code = ?) AND (? = 0 OR p.city_id = ? OR p.city_id IS NULL) LIMIT 1");
        $postStmt->execute([$postcode, $postcode, $countryCode, $countryCode, $cityId, $cityId]);
        $point = $postStmt->fetch(PDO::FETCH_ASSOC);
        
        if (!$point) {
            $postStmt2 = $pdo->prepare("SELECT lat, lng FROM postcodes WHERE postcode_normalized = ? OR postcode = ? LIMIT 1");
            $postStmt2->execute([$postcode, $postcode]);
            $point = $postStmt2->fetch(PDO::FETCH_ASSOC);
        }
    } catch (Exception $e) {}
    
    echo json_encode($point ? ['found'=>true, 'lat'=>(float)$point['lat'], 'lng'=>(float)$point['lng']] : ['found'=>false], JSON_UNESCAPED_UNICODE);
    exit;
}

if (isset($_GET['ajax']) && $_GET['ajax'] === '1') {
    header('Content-Type: application/json; charset=utf-8');
    echo json_encode(['listings' => $mapListings], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    exit;
}

