const cityCenterCoords = <?= json_encode($cityCoordinates, JSON_UNESCAPED_UNICODE) ?>;
const countryCenterCoords = <?= json_encode($countryCoordinates, JSON_UNESCAPED_UNICODE) ?>;

const listingMap = L.map('listingMap').setView([51.5, 10.0], 4);
L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
  maxZoom: 19,
  attribution: '&copy; OpenStreetMap contributors'
}).addTo(listingMap);

let mapListings = <?= json_encode($mapListings, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
const mapCategories = <?= json_encode($mapCategories, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
const mapCities = <?= json_encode($mapCities, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) ?>;
let mapMarkers = [];
let searchCenter = null;
let searchCenterMarker = null;
let activeRadius = <?= (int)$distanceKm ?>;
let radiusCircle = null;
let locationBoundary = null;
let activeModule = '<?= e($moduleFilter) ?>';
let activeCategory = '<?= (int)$categoryFilter ?>';

function isValidMapCoordinate(listing) {
  const lat = Number(listing.latitude), lng = Number(listing.longitude);
  return Number.isFinite(lat) && Number.isFinite(lng) &&
    lat >= 30 && lat <= 65 && lng >= -15 && lng <= 50;
}

function escapePopupText(value) {
  return String(value || '').replace(/[&<>"']/g, function (c) {
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c];
  });
}

function getFilteredListings() {
  let list = mapListings.filter(isValidMapCoordinate);
  
  if (searchCenter && radiusCircle) {
    list = list.filter(function (it) {
      return distanceKm(searchCenter[0], searchCenter[1], Number(it.latitude), Number(it.longitude)) <= activeRadius;
    });
  }
  return list;
}

function renderListings(fit) {
  mapMarkers.forEach(function (marker) { listingMap.removeLayer(marker); });
  mapMarkers = [];
  
  const validListings = getFilteredListings();
  const bounds = [];
  
  validListings.forEach(function (listing) {
    const lat = Number(listing.latitude);
    const lng = Number(listing.longitude);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
    
    const pShort = Number(listing.price || 0) >= 1000 
      ? (Number(listing.price || 0) / 1000).toLocaleString('de-DE', {maximumFractionDigits: 1}) + 'k' 
      : Number(listing.price || 0).toLocaleString('de-DE', {maximumFractionDigits: 0});
      
    const markerIcon = L.divIcon({
      className: 'custom-map-pin',
      html: '<div class="pin-bubble"><span>€ ' + pShort + '</span></div>',
      iconSize: [60, 30],
      iconAnchor: [30, 30]
    });
    
    const marker = L.marker([lat, lng], {icon: markerIcon}).addTo(listingMap);
    mapMarkers.push(marker);
    
    const price = Number(listing.price || 0).toLocaleString('de-DE', {maximumFractionDigits: 0});
    const safeTitle = escapePopupText(listing.title || '');
    const safeDesc = escapePopupText(listing.description || '').substring(0, 110);
    const safeCity = escapePopupText(listing.city_name || listing.country_name || '');
    
    const cardHtml = '<div class="map-hover-card">' +
      '<div class="map-popup-image-wrapper">' +
        '<img src="' + String(listing.image_url || '') + '" alt="" class="map-popup-image">' +
        '<span class="map-popup-badge">' + safeCity + '</span>' +
      '</div>' +
      '<div class="map-popup-body">' +
        '<strong class="map-popup-title">' + safeTitle + '</strong>' +
        (safeDesc ? '<p class="map-popup-desc">' + safeDesc + (listing.description && listing.description.length > 110 ? '...' : '') + '</p>' : '') +
        '<div class="map-popup-footer">' +
          '<div class="map-popup-price-tag"><span class="cur">€</span> ' + price + '</div>' +
          '<a class="map-popup-link" target="_blank" rel="noopener" href="<?= e(BASE_URL) ?>/pages/listing.php?id=' + Number(listing.id) + '"><?= e(t('common.view') ?: 'Görüntüle') ?></a>' +
        '</div>' +
      '</div>' +
      '</div>';
    
    marker.bindPopup(cardHtml, {
      className: 'map-custom-popup',
      maxWidth: 280,
      offset: [0, -22],
      autoPan: true,
      autoPanPaddingTopLeft: L.point(20, 80),
      autoPanPaddingBottomRight: L.point(20, 20),
      closeButton: true
    });
    
    marker.on('mouseover', function () {
      this.openPopup();
    });
    
    bounds.push([lat, lng]);
  });
  
  if (fit && bounds.length) {
    if (bounds.length === 1) {
      listingMap.setView(bounds[0], 11);
    } else {
      listingMap.fitBounds(bounds, {padding: [35, 35], maxZoom: 13});
    }
  }
  
  const countEl = document.getElementById('mapMainCount');
  if (countEl) countEl.textContent = validListings.length;
  
  const statusEl = document.getElementById('mapPostcodeStatus');
  if (statusEl && searchCenter) {
    statusEl.textContent = validListings.length + ' ilan çember içinde';
  }
}

function clearLocationBoundary() {
  if (locationBoundary) {
    listingMap.removeLayer(locationBoundary);
    locationBoundary = null;
  }
  listingMap.setMaxBounds(null);
}

function showCountryBoundary(countryCode) {
  clearLocationBoundary();
  if (!countryCode) return;
  
  const code = String(countryCode).toLowerCase();
  const feature = staticCountryBoundaries.features.find(function (f) {
    return f.properties && f.properties.code === code;
  });
  
  if (feature) {
    locationBoundary = L.geoJSON(feature, {
      style: {
        color: '#dc2626',
        weight: 3,
        opacity: 0.95,
        fillColor: '#ef4444',
        fillOpacity: 0.05,
        dashArray: '8 6',
        interactive: false
      }
    }).addTo(listingMap);
    
    const bounds = locationBoundary.getBounds();
    if (bounds.isValid()) {
      listingMap.fitBounds(bounds, {padding: [20, 20], animate: false});
    }
  }
}

function updateRadiusArea(fit) {
  if (!searchCenter) return;
  
  const radiusMeters = activeRadius * 1000;
  
  if (!radiusCircle) {
    radiusCircle = L.circle(searchCenter, {
      radius: radiusMeters,
      color: '#dc2626',
      weight: 3,
      opacity: 0.9,
      dashArray: '8 6',
      fillColor: '#ef4444',
      fillOpacity: 0.08,
      interactive: false
    }).addTo(listingMap);
  } else {
    radiusCircle.setLatLng(searchCenter);
    radiusCircle.setRadius(radiusMeters);
  }
  
  if (!searchCenterMarker) {
    searchCenterMarker = L.circleMarker(searchCenter, {
      radius: 7,
      color: '#ffffff',
      weight: 3,
      fillColor: '#dc2626',
      fillOpacity: 1,
      interactive: false
    }).addTo(listingMap);
  } else {
    searchCenterMarker.setLatLng(searchCenter);
  }
  
  const rBar = document.getElementById('mapRadiusControlBar');
  if (rBar) rBar.style.display = 'block';
  
  const rText = document.getElementById('radiusValText');
  if (rText) rText.textContent = activeRadius + ' km';
  
  const rSlider = document.getElementById('mapRadiusRange');
  if (rSlider) rSlider.value = activeRadius;
  
  if (fit) {
    listingMap.fitBounds(radiusCircle.getBounds(), {padding: [24, 24]});
  }
  
  renderListings(false);
}

function distanceKm(aLat, aLng, bLat, bLng) {
  const r = 6371, rad = Math.PI / 180;
  const dLat = (bLat - aLat) * rad, dLng = (bLng - aLng) * rad;
  const x = Math.sin(dLat / 2) ** 2 + Math.cos(aLat * rad) * Math.cos(bLat * rad) * Math.sin(dLng / 2) ** 2;
  return 2 * r * Math.atan2(Math.sqrt(x), Math.sqrt(1 - x));
}

function setMapLoading(isLoading) {
  const loader = document.getElementById('mapLoading');
  const overlay = document.getElementById('mapLoadingOverlay');
  if (loader) loader.hidden = !isLoading;
  if (overlay) overlay.hidden = !isLoading;
}

function fetchMapData(fitLocation) {
  setMapLoading(true);
  
  const countrySelect = document.getElementById('mapCountry');
  const citySelect = document.getElementById('mapCity');
  const countryId = countrySelect.value;
  const cityId = citySelect.value;
  const countryCode = countrySelect.options[countrySelect.selectedIndex]?.dataset.code || '';
  const cityName = citySelect.options[citySelect.selectedIndex]?.textContent || '';
  
  const url = new URL(window.location.href);
  url.searchParams.set('ajax', '1');
  if (countryId) url.searchParams.set('country', countryId); else url.searchParams.delete('country');
  if (cityId) url.searchParams.set('city', cityId); else url.searchParams.delete('city');
  if (activeModule) url.searchParams.set('module', activeModule); else url.searchParams.delete('module');
  if (activeCategory && activeCategory !== '0') url.searchParams.set('category_id', activeCategory); else url.searchParams.delete('category_id');
  
  fetch(url.toString())
    .then(function (res) { return res.json(); })
    .then(function (data) {
      mapListings = data.listings || [];
      
      if (fitLocation) {
        if (cityId && cityName) {
          clearLocationBoundary();
          const cityKey = cityName.trim().toLowerCase();
          const cityCoords = cityCenterCoords[cityKey];
          if (cityCoords) {
            listingMap.setView(cityCoords, 11);
          } else {
            const valid = mapListings.filter(isValidMapCoordinate);
            if (valid.length > 0) {
              const bounds = valid.map(it => [Number(it.latitude), Number(it.longitude)]);
              listingMap.fitBounds(bounds, {padding: [30, 30], maxZoom: 12});
            }
          }
        } else if (countryId && countryCode) {
          showCountryBoundary(countryCode);
        } else {
          clearLocationBoundary();
          listingMap.setView([51.5, 10.0], 4);
        }
      }
      
      renderListings(false);
      setMapLoading(false);
    })
    .catch(function () {
      setMapLoading(false);
    });
}

const radiusSlider = document.getElementById('mapRadiusRange');
if (radiusSlider) {
  radiusSlider.addEventListener('input', function () {
    activeRadius = Number(this.value);
    const rText = document.getElementById('radiusValText');
    if (rText) rText.textContent = activeRadius + ' km';
    updateRadiusArea(false);
  });
}

document.getElementById('mapCountry').addEventListener('change', function () {
  const city = document.getElementById('mapCity');
  const cities = mapCities[this.value] || [];
  city.innerHTML = '<option value="">' + <?= json_encode(t('common.all') ?: 'Tüm Şehirler') ?> + '</option>';
  cities.forEach(function (item) {
    const option = document.createElement('option');
    option.value = item.id;
    option.textContent = item.name;
    city.appendChild(option);
  });
  city.disabled = !this.value;
  city.value = '';
  fetchMapData(true);
});

document.getElementById('mapCity').addEventListener('change', function() {
  fetchMapData(true);
});

document.querySelectorAll('.map-category-item, .map-subcategory').forEach(function (button) {
  button.addEventListener('click', function () {
    const group = this.closest('.map-category-group');
    
    if (group && this.classList.contains('map-category-item')) {
      const sub = group.querySelector('.map-subcategories');
      const opening = sub && sub.hasAttribute('hidden');
      
      document.querySelectorAll('.map-subcategories').forEach(function (item) { item.hidden = true; });
      document.querySelectorAll('.map-category-item').forEach(function (item) {
        item.classList.remove('is-active');
        item.setAttribute('aria-expanded', 'false');
        item.setAttribute('aria-pressed', 'false');
      });
      
      this.classList.add('is-active');
      this.setAttribute('aria-pressed', 'true');
      
      if (sub && opening) {
        sub.hidden = false;
        this.setAttribute('aria-expanded', 'true');
      }
    } else {
      document.querySelectorAll('.map-category-item, .map-subcategory').forEach(function (item) {
        item.classList.remove('is-active');
        item.setAttribute('aria-pressed', 'false');
      });
      this.classList.add('is-active');
      this.setAttribute('aria-pressed', 'true');
    }
    
    activeModule = this.dataset.module || '';
    activeCategory = this.dataset.category || '0';
    
    fetchMapData(false);
  });
});

document.getElementById('mapResetButton').addEventListener('click', function () {
  searchCenter = null;
  setMapLoading(false);
  clearLocationBoundary();
  
  if (radiusCircle) { listingMap.removeLayer(radiusCircle); radiusCircle = null; }
  if (searchCenterMarker) { listingMap.removeLayer(searchCenterMarker); searchCenterMarker = null; }
  
  const rBar = document.getElementById('mapRadiusControlBar');
  if (rBar) rBar.style.display = 'flex';
  
  document.getElementById('mapPostcode').value = '';
  document.getElementById('mapCountry').value = '';
  document.getElementById('mapCity').innerHTML = '<option value="">' + <?= json_encode(t('common.all') ?: 'Tüm Şehirler') ?> + '</option>';
  document.getElementById('mapCity').disabled = true;
  document.getElementById('mapPostcodeStatus').textContent = '';
  
  document.querySelectorAll('.map-category-item, .map-subcategory').forEach(function (item) { item.classList.remove('is-active'); });
  const allCat = document.querySelector('.map-category-item[data-module=""][data-category=""]');
  if (allCat) {
    allCat.classList.add('is-active');
    allCat.setAttribute('aria-pressed', 'true');
  }
  document.querySelectorAll('.map-subcategories').forEach(function (item) { item.hidden = true; });
  
  activeModule = '';
  activeCategory = '0';
  activeRadius = 25;
  
  fetchMapData(true);
});

document.getElementById('mapPostcodeForm').addEventListener('submit', function (event) {
  event.preventDefault();
  const input = document.getElementById('mapPostcode');
  const status = document.getElementById('mapPostcodeStatus');
  const postcode = input.value.trim();
  if (!postcode) {
    status.textContent = <?= json_encode(t('map.enter_postcode') ?: 'Lütfen bir posta kodu veya şehir girin') ?>;
    return;
  }
  
  status.textContent = <?= json_encode(t('map.loading') ?: 'Aranıyor...') ?>;
  
  const countrySelect = document.getElementById('mapCountry');
  const citySelect = document.getElementById('mapCity');
  const countryCode = countrySelect.options[countrySelect.selectedIndex]?.dataset.code || '';
  const normalizedPostcode = postcode.replace(/\s+/g, '').toUpperCase();
  
  const lookupUrl = new URL(window.location.href);
  lookupUrl.searchParams.set('ajax', 'postcode');
  lookupUrl.searchParams.set('postcode', normalizedPostcode);
  if (countryCode) lookupUrl.searchParams.set('country', countryCode);
  if (citySelect.value) lookupUrl.searchParams.set('city', citySelect.value);
  
  function applyFoundLocation(lat, lng) {
    searchCenter = [lat, lng];
    updateRadiusArea(true);
  }
  
  fetch(lookupUrl.toString())
    .then(function (response) { if (!response.ok) throw new Error('db-postcode-failed'); return response.json(); })
    .then(function (result) {
      if (result && result.found && Number.isFinite(result.lat) && Number.isFinite(result.lng)) {
        applyFoundLocation(Number(result.lat), Number(result.lng));
      } else {
        const params = new URLSearchParams({
          format: 'json',
          q: postcode,
          limit: '1'
        });
        if (countryCode) params.set('countrycodes', countryCode.toLowerCase());
        
        return fetch('https://nominatim.openstreetmap.org/search?' + params.toString())
          .then(function (geoRes) { return geoRes.json(); })
          .then(function (geoData) {
            if (geoData && geoData.length > 0) {
              applyFoundLocation(Number(geoData[0].lat), Number(geoData[0].lon));
            } else {
              status.textContent = <?= json_encode(t('map.postcode_not_found') ?: 'Konum bulunamadı') ?>;
            }
          });
      }
    })
    .catch(function () {
      status.textContent = <?= json_encode(t('map.postcode_not_found') ?: 'Konum bulunamadı') ?>;
    });
});

